Definition fm_st (st : mstate) (g : aptr) : mstate := queue_st LFree g (put_meta g meta0 st).

Lemma free_meta_eq {R} st g (k : mstate -> M R) bail : free_meta g st k bail = k (fm_st st g).
Proof.
