Definition data_of (r : meta) : meta := m_set_prev None (m_set_next None r).

Lemma data_of_eq r r' :
  data_of r = data_of r' <->
  (m_mem r = m_mem r' /\ m_avail r = m_avail r' /\ m_freed r = m_freed r' /\ m_last_idx r = m_last_idx r'
