(* [comment removed for export] *)
Lemma linked_ext st st' l :
  (forall x, In x (removelast l) -> m_next (MR st' x) = m_next (MR st x)) ->
  (forall x, In x (tl l) -> m_prev (MR st' x) = m_prev (MR st x)) ->
