Lemma dequeue_next x : m_next (MR st' x) =
  if aptr_eqb x m then None
  else if optr_eqb (m_next mr) (Some m) then m_next (MR st x)
  else if optr_eqb (m_prev mr) (Some x) then m_next mr else m_next (MR st x).
Proof.
