Lemma queue_prev x : m_prev (MR st' x) =
  match get_head st h with
  | Some a => if aptr_eqb x a then Some g
              else if aptr_eqb x g then m_prev (MR st a)
              else m_prev (MR st x)
  | None => if aptr_eqb x g then Some g else m_prev (MR st x)
