Lemma dll_ends st a r : dll st (a :: r) ->
  let q := match r with [] => a | b :: _ => b end in
  let p := List.last r a in
  m_next (MR st a) = Some q /\ m_prev (MR st q) = Some a /\ m_next (MR st p) = Some a /\ m_prev (MR st a) = Some p
  /\ linked st (a :: r).
